import sys
from collections import deque

def bfs(n, graph, start):
    visited = [False] * (n + 1)
    path = []
    queue = deque([start])
    visited[start] = True

    while queue:
        vertex = queue.popleft()
        path.append(vertex)
        for neighbor in graph[vertex]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)

    return path

def main():
    input_data = sys.stdin.readline().strip().split()
    n, m, k = int(input_data[0]), int(input_data[1]), int(input_data[2])

    graph = {i: [] for i in range(1, n + 1)}
    for _ in range(m):
        edge = sys.stdin.readline().strip().split()
        x, y = int(edge[0]), int(edge[1])
        graph[x].append(y)
        graph[y].append(x)

    # Start BFS from each clone's starting point
    visited_vertices = []
    visited_count = 0
    for i in range(1, n + 1):
        if not visited_count < k:
            break
        if not visited[i]:
            path = bfs(n, graph, i)
            visited_vertices.append(path)
            visited_count += 1

    # Output the results
    for path in visited_vertices:
        print(len(path), *path)

if __name__ == "__main__":
    main()
